-- TMF Community Support System - M2 "Database ready" seed (02 seed data)
-- Generated by /workspace/tmf/seed/gen/build.py. All seed ids match the LIKE pattern
--   '5eed____-5eed-4eed-8eed-5eed5eed5eed'  and all seed auth emails match 'seed.%@example.com'.
-- Run order: 01_seed_auth_users.sql -> 02_seed.sql -> 03_seed_verify.sql ; cleanup: 04_seed_cleanup.sql
--
-- Requires 01_seed_auth_users.sql (42 seed accounts + their trigger-provisioned profiles).
-- Runs as postgres (SQL Editor) in ONE transaction. RLS does not apply to the table owner and the
-- protect_* triggers let non-API roles through, so admin-type values are seeded directly.
-- Idempotent: fixed ids + "on conflict (id) do nothing"; the updates set fixed values.
-- Trigger effects: refresh_campaign_amount recomputes campaigns.amount_raised from successful money
-- donations (amount_raised is never written here); contact_messages_notify_admins adds one
-- notification per administrator for each NEW contact message (non-seed administrators too);
-- the *_status_notification triggers fire on UPDATE only, so rows inserted with a final status do
-- NOT notify anyone - a realistic notification history is inserted explicitly instead.
begin;

do $$
declare v_auth int; v_prof int;
begin
  select count(*) into v_auth from auth.users where id::text like '5eed____-5eed-4eed-8eed-5eed5eed5eed' and email like 'seed.%@example.com';
  select count(*) into v_prof from public.profiles where id::text like '5eed____-5eed-4eed-8eed-5eed5eed5eed';
  if v_auth <> 42 or v_prof <> 42 then
    raise exception 'Expected 42 seed auth users and profiles, found % / %. Run 01_seed_auth_users.sql first.', v_auth, v_prof;
  end if;
end $$;

